globalThis.ANDE_CHUNKS["0f4bedbca55de69bb8cc18c1fb14b9627a7d95a1d20cd22c117e8db9d2c71bab"] = [{"id":"deepseek:01416da2-3c8a-4a20-bbb3-1c925d0facf1","sourceKey":"deepseek","company":"DeepSeek","title":"深度学习研发工程师","city":"海淀区","category":"全栈开发/算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/01416da2-3c8a-4a20-bbb3-1c925d0facf1","duty":"【团队使命】\n以\"算法+系统\"的双重视角贯穿训练到部署全链路，让模型在精度与性能的平衡中发挥最大价值。\n【岗位类别】：实习/全职\n【岗位职责】\n1. 既懂算法又懂系统。\n2. 既能调精度也能调性能。\n3. 既考虑训练也考虑推理部署。","requirements":"【岗位要求】\n1. 了解深度学习的各类模型，具备较强的工程能力。\n2. 编程能力出色，熟练掌握Python和C++。\n3. 熟练掌握深度学习各类模型架构的使用和设计。\n4. 在领域内知名比赛取得优异成绩者优先。","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:0238c1b1-7f2d-4b53-84da-581127a62954","sourceKey":"deepseek","company":"DeepSeek","title":"AI创作数据产品经理","city":"拱墅区/海淀区","category":"模型数据策略","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/0238c1b1-7f2d-4b53-84da-581127a62954","duty":"【团队使命】\n探索AI创造力的上限，以人类最高审美标准，驱动模型创作能力持续进化。写作与审美是人类认知中最抽象、最深邃的疆域——我们坚信这并非AI的壁垒，不过是它尚未抵达的前沿。人类千年积累的智慧与审美，将是孕育AGI的起点，而绝非它的终点。我们将以极致的数据质量与科学的评测体系，让这一切从信仰变为现实。\n【岗位类别】：实习/全职\n【工作职责】\n1.文艺写作方向：负责文学文本（小说、诗歌、散文等）场景下的优化方向判断与效果评测，制定数据质量标准与评估体系，驱动模型文学审美与写作能力持续提升，探索并拓展AI文学创作力的上限。\n2.功能写作方向：负责实用文本（论文、报告、方案、公文、文案等）场景下的优化方向判断与效果评测，定义不同文体的理想输出标准，与搜索/Agent方向协同，在任何环境中给用户提供真正可用的文本。","requirements":"【岗位要求】\n1.熟悉大模型写作的当前水准：了解不同模型的风格倾向与能力边界，对大模型写作的难点和瓶颈有基于大量使用的体感认知与独立思考。\n2.具备卓越的文本审美与判断力：在文学创作或实用文本写作领域有长期、扎实的实践，对文字有极高的敏感度，能对文本质量做出精准判断，将写得“好不好”拆解为具体的能力维度与可落地的优化方案。\n3.具备模型认知与数据生产意识：了解模型训练基础知识，能将审美判断转化为可度量的评测维度与数据规范；具备一定动手能力，能借助工具高效支撑数据生产与质量校验。\n4.拥有好奇心与自驱力：热爱创作，持续关注AI创作领域的前沿进展，对AI与人文创作的结合有探索热情，相信AI的创作能力存在更高的可能性。","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:08d2d307-61f9-4465-ba5f-f8eeb20d675b","sourceKey":"deepseek","company":"DeepSeek","title":"HR团队","city":"拱墅区/海淀区","category":"HR团队","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/08d2d307-61f9-4465-ba5f-f8eeb20d675b","duty":"【团队使命】\n我们相信AGI不只是技术的跃迁，更是对人类潜能的重新定义。我们的使命，是让AGI成为现实——而这趟旅程的起点与终点，始终是人。\n我们相信真正的创新来自长期主义的坚持，来自对人才深度的信任。\n作为HR团队，我们是这家以“人”为核心的公司的基石。我们寻找能以深刻洞见识别人才、以长期主义培育土壤、以务实精神构建组织的同行者。在这里，HR不仅是支持部门，更是AGI梦想的共建者。\n招聘方向【全职】：招聘HR方向、综合服务HR方向\n招聘HR方向\n【岗位职责】\n1.充分理解、深入分析部门对于人才的需求，将用人需求转化为可执行的寻访策略。\n2.对海内外高潜人才进行系统性Mapping，建立并维护优质人才资源池，与候选人保持长期、真诚的互动，准确识别其能力特质与职业诉求，精准匹配岗位。\n3.全流程跟进招聘进度，关注行业人才动态，用数据持续分析和优化招聘策略，提升效率与质量。\n4.跟踪候选人入职","requirements":"【任职要求】\n1.踏实细心，有责任心，善于主动发现问题并推动解决，对细节敏感。\n2.亲和力好，善于换位思考，能和员工建立顺畅的沟通关系。\n3.愿意学习并落地新工具、新方法，不排斥事务性工作的系统化改进。\n4.对AGI有长期信心。","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:0a317cbb-df30-4770-b0d6-c51bf4e2133b","sourceKey":"deepseek","company":"DeepSeek","title":"前端 / 客户端开发工程师","city":"拱墅区/海淀区","category":"全栈开发/算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/0a317cbb-df30-4770-b0d6-c51bf4e2133b","duty":"【团队使命】\nAGI 时代，人类与机器交互的革命已经开启，AI 赋予了产品主动思考的能力与无限的可能，我们正站在时代的前沿，将智能通过用户界面具象化，建立人类与 AI 相互触达、沟通、协作的桥梁，在这里，你将：\n1.探索 AGI 时代尚未被定义的人机交互与产品可能，从对话式交互走向 Agent 协作、主动式服务等新范式，定义人与 AI 协同工作的新方式。\n2.持续优化 DeepSeek 面向各类用户的终端产品，打磨细节，让性能与体验始终先人一步。\n招聘方向【实习/全职】：前端开发方向、客户端开发方向\n前端开发方向\n【工作职责】\n负责 DeepSeek 网页版、开放平台等服务的迭代开发，探索、预研 Agent 等概念的新交互范式，寻找 AGI 时代的人机交互方式。深度参与前端设计与实现，持续优化体验，服务千万日活用户，发现 AI 产品的更多可能性。\n【工作职责】\n负责 DeepSeek iO","requirements":"【岗位要求】\n1.熟练使用 JavaScript、TypeScript。\n2.熟练使用至少一个主流前端框架。\n3.熟练掌握 HTML、CSS、HTTP 等前端基础知识。\n4.熟练掌握各类前端技术加分（如 Node.js，前端工具链，WASM 等）。\n5.对用户体验、交互操作及用户需求分析等有一定了解，有产品或界面设计经验者优先。\n6.有优秀的个人技术产品、开源作品，或活跃的开源社区贡献者优先。\n客户端开发方向\n【岗位要求】\n1.具备 iOS / Android 原生开发经验，熟悉 Swift / Objective-C 或 Kotlin / Java 等编程语言（iOS、Android 有一方面熟练即可）。\n2.对应用性能敏感，能熟练定位性能瓶颈并优化。\n3.对新技术抱有热情，具备扎实的编程能力、优秀的设计能力和代码品味，具有强烈的责任心和主动性。\n4.具备用户洞察能力，有产品、交互设计相","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:141a78cd-784f-4139-9b72-8046afeec4e4","sourceKey":"deepseek","company":"DeepSeek","title":"专业领域数据产品经理（小语种、医学法律等学科）","city":"拱墅区/海淀区","category":"模型数据策略","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/141a78cd-784f-4139-9b72-8046afeec4e4","duty":"【团队使命】\n知识塑造了文明的骨骼，专业则赋予它精度与锋芒。领域专家的判断力是校准模型的标尺，持续定义知识选取、推理质量与表达水准的上限。我们相信，专业不止于知识本身，它是精准的判断、高效的生产力、也是对表达品质的追求。这些人类在各领域最深厚的积累，正是AGI智识涌现的源头。我们要做的，是让它真正流入模型，用人类的深度，拓展智能的边界。\n【岗位类别】：实习/全职\n【工作职责】\n1.构建模型评测体系：在专精或通用领域，搭建科学的评估维度，开发自动化的评估方式，定位模型短板，为版本迭代提供清晰、可解释的依据。\n2.设计优化策略：挖掘各专业领域用户需求，定义优秀回答的标准，设计逼近优秀回答的优化路径。\n3.建设高质量数据：落地数据制作流程，交付兼具实用与审美价值的数据，优化模型的智识能力。","requirements":"【岗位要求】\n1.在某知识垂类有扎实的专业积累，或具备优秀高校的求学或研究经历（硕/博，或成绩优异的本科生均可）。我们不限定专业方向，每一个领域的纵深都可能是模型下一次突破的起点。\n2.能凭借自身专业积累，从知识准确性、推理质量、表达水准等多个维度对模型回答形成清晰的优劣判断，说明问题所在及原因，并从个案中归纳出共性的体验问题与优化方向。\n3.使用过多个主流大模型，能够敏锐感知不同模型的能力边界与差异，能就近期某项模型能力、评测方式或技术进展说明其内容与自己的判断。\n4.对模型训练与优化的基本原理和技术有所了解，能将专业知识与审美判断转化为可度量的评测维度与数据规范；熟悉Prompt Engineering，能通过Vibe Coding等方式快速验证想法、提升工作效率者优先。","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:1c7e328d-3da9-4129-a938-21edfd77d38c","sourceKey":"deepseek","company":"DeepSeek","title":"IDC数据中心团队","city":"拱墅区/海淀区/察哈尔右翼前旗","category":"运维","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/1c7e328d-3da9-4129-a938-21edfd77d38c","duty":"","requirements":"","description":"【团队使命】\n每一代人都会遇到属于自己的基础设施革命。过去是铁路、电网和互联网，今天则是支撑 AI 发展的超大规模算力集群。\n我们不只是在建设数据中心，更是在建设未来 AI 智能体赖以生存的基础设施。电力、制冷、网络和计算系统将在这里深度耦合，每一度电力、每一瓦制冷量、每一次调度都直接影响最终的算力输出。\n行业惯例只是历史经验，我们将从物理和工程的极限重新出发，持续探索数据中心系统在效率、可靠性、自动化和弹性上的能力边界。\n如果你热爱工程、乐于探索，并希望亲手构建 AGI 时代的基础设施底座，我们期待与你一起定义未来。\n招聘方向【全职】：数据中心基础设施运营方向、数据中心规划设计方向、数据中心现场方向\n【你会获得】\n1.直接参与AI时代最核心的基础设施建设。从传统IDC到AI智算中心，从风冷到液冷，从MW级机房到GW级园区，你将投身到AI 时代最前沿基础设施项目。\n2.学习不设边界。你不会","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:1df4597d-6039-4392-9954-0df72510f415","sourceKey":"deepseek","company":"DeepSeek","title":"AI 搜索算法 / 架构工程师","city":"海淀区","category":"全栈开发/算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/1df4597d-6039-4392-9954-0df72510f415","duty":"【团队使命】\n搜索是 AGI 感知世界的原生感官。\n我们正在打造下一代 AI 原生的通用搜索引擎，它不再只是返回十条蓝色链接，而是让每一次提问都被真正理解，在全球范围内找到准确、及时、权威的信息。\n我们将探索 LLM 与搜索引擎的深度融合，让搜索成为 LLM 理解世界的重要基础设施：任何语言、任何模态都能被平等地检索。\n在这里，你将参与构建极致简洁 & 轻量的 LLM-based 检索系统，承载全球海量的搜索请求，在成本、延迟与效果之间寻找最优平衡。\n招聘方向【实习/全职】：AI 搜索算法方向、AI 搜索架构方向\nAI 搜索算法方向\n【工作职责】\n1.负责 DeepSeek 搜索引擎的核心算法优化，包括 query 理解、召回、排序、索引筛选、质量评估等方向，让搜索结果更准确、权威、实时，更适合 LLM 理解与使用。\n2.建设多语言、多场景、多模态的搜索能力，解决不同语言与地区、不同内容生","requirements":"【岗位要求】\n1.至少熟悉机器学习、深度学习、信息检索中的一个方向。\n2.对搜索和大模型结合感兴趣，既愿意持续学习新技术，也愿意深入真实业务问题，从 badcase 与 用户反馈中定位系统短板。\n3.具备良好的工程落地能力与意识，不做过度设计，能够在成本与延时约束下完成算法落地。\n4.沟通直接、协作意识强，具备优秀的跨团队协作能力。\n5.有搜索、推荐、广告、RAG、chatbot 等大规模在线系统经验者优先。\nAI 搜索架构方向\n【岗位要求】\n1.熟练掌握 C++ 或 Rust，熟悉 Python、SQL 等常用语言。工程能力强。\n2.熟悉数据密集型系统开发和性能优化。有良好的系统设计品味。\n【加分项】\n1.熟悉大规模分布式向量检索技术（稠密/稀疏/多向量），熟悉 RDMA 高性能通信技术。\n2.熟悉 Pytorch、CUDA 等模型推理技术，了解 KVCache 存储系统，有模型部署和推","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:25dcb4d9-d250-43ce-8f56-159ddba47c10","sourceKey":"deepseek","company":"DeepSeek","title":"预训练（数据/算法）研究员","city":"海淀区","category":"深度学习研究员","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/25dcb4d9-d250-43ce-8f56-159ddba47c10","duty":"","requirements":"","description":"【团队使命】\n1.探索智能的本质，持续追求 AGI，通过对算法和数据策略的深入研究，构建更强和更快的模型，并确保其始终服务于全人类的共同利益与福祉。\n2.专注于软硬件协同的模型结构创新、高效优化器与训练动力学研究，建立科学的 scaling law 指导规划，攻克训练与推理加速瓶颈，并探索非共识的新型网络架构，持续推动预训练领域的基础理论边界。\n3.如何寻找蒙尘的富矿，并淘洗炼制成可用的智能燃料，是一门极难的硬功夫。我们以亿万数据筑就模型智能的坚实底座，更要用普惠的方式，把这份属于全人类的财富，重新还给全人类。\n4.致力于搭建真实世界与 AGI 之间的数据桥梁，构建高质量、可追溯、可复现的数据资产，打通从数据治理到智能涌现的确定性路径；建立严谨的数据质量体系与配比策略，通过数据的桥梁将世界知识、任务结构、行为轨迹和反馈信号输送进模型，为模型赋予跨领域理解、推理、规划、工具使用和对齐的能力。","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:27f0675d-5ffd-48d9-a36c-f340a443dc8b","sourceKey":"deepseek","company":"DeepSeek","title":"IT 基础设施团队","city":"拱墅区/海淀区","category":"运维","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/27f0675d-5ffd-48d9-a36c-f340a443dc8b","duty":"【团队使命】\n大模型训练能不能跑满带宽，取决于我们的网络配置；GPU 集群能不能发挥出纸面性能，取决于我们的固件和压测基线；新员工第一天能不能顺畅开工，取决于我们的流程有没有提前打通。\n我们不写模型，但我们决定模型能跑多快。我们不写业务代码，但我们决定代码能不能顺利部署。基础设施不是背景板 —— 它是上限。\n从单块 GPU 的固件参数，到跨地域万卡集群的网络拓扑；从数据中心的 RDMA 链路，到每个工位的网络接入和设备交付 —— 我们负责让每一层硬件、网络和办公环境在真实负载下稳定运行。\n我们不满足于 \"能用\"。硬件方向，我们追求接近物理极限的性能与可靠性，每一个配置参数都要有理由，每一次变更都要有基线对比；桌面方向，我们追求零摩擦的使用体验，让每一个人都能在第一时间拿到可用的工具，专注于本职工作。\n两个方向，同一个标准：每一层都不成为瓶颈。\n招聘方向【实习/全职】：系统硬件&网络方向、I","requirements":"【任职要求】\n1.扎实的技术功底，在硬件架构（CPU/GPU/ 存储 / 网络互联）或网络技术（路由协议、RDMA、数通）中至少一个方向有深入理解或有强烈兴趣，能从实现细节角度分析和解决问题。\n2.熟悉 Python 或 Go，能独立开发压测、配置管理、自动化运维等工具；具备数据建模能力。\n3.强烈的好奇心与求知欲，主动跟踪技术前沿，对每一个细节都有打破砂锅的冲劲。\n4.良好的沟通协调能力，能在多团队协作、高压环境下稳定决策与执行。\n【加分项】（不强制，欢迎有热情的白纸同学）\n1.有大规模 GPU 集群（NVIDIA/Ascend）运维或压测经验。\n2.熟悉 Redfish/IPMI；有 Rust 开发经验。\n3.了解硬件底层规范与实现，包括 ACPI、OpenBMC、BIOS/UEFI、PCIe、I2C/I3C 等，能从固件或总线层面分析和定位问题。\n4.有跨地域容灾与 DCI 项目经验","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:2eb2e75d-29f3-47b5-bb10-39f12547d398","sourceKey":"deepseek","company":"DeepSeek","title":"服务端开发工程师","city":"拱墅区/海淀区","category":"全栈开发/算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/2eb2e75d-29f3-47b5-bb10-39f12547d398","duty":"【团队使命】\n服务端开发工程师会与大模型研究员深入协作，深入到大模型的研究之中，共同构建用于推进模型智能边界的工程基建。在这里，我们离大模型研究前沿足够近，做出来的东西马上有来自研究一线的反馈。平台的可靠与好用，直接决定了大模型研究的效率和提升智能上限的速度。\n这是一次长期主义的、大规模的投入，我们欢迎应届毕业生及两年以内经验的新鲜力量加入，同时也特别期待拥有2至10年工作经验的资深工程师——资深工程师将是本次招聘的重点关注对象（对特别优秀的候选人，年限要求可适当放宽）。本次招聘规模约150人，工作地点以北京为主，部分岗位或可选择杭州。\n我们在寻找那个在一线钻研技术、热爱代码的你。\n招聘方向【实习/全职】：大模型研究平台方向、Agent 框架组件方向、研发效率基建方向、DeepSeek API 方向、线上服务方向\n投递时不限方向，我们会根据你的背景与意愿确定具体方向，也可能在面试过程中随着","requirements":"岗位要求\n1.具备出色的编程能力、系统设计能力和技术判断力，能独立负责重要系统的设计与落地。\n2.具备丰富的研发经验，在大规模分布式系统、数据平台、任务和调度系统等方向有扎实积累。\n3.扎实的编程与计算机基础，熟练掌握至少一种通用编程语言，深入理解分布式系统、存储与服务架构。\n4.具备良好的抽象能力、Owner 意识和跨团队协作能力，能在快速变化的需求中推动复杂问题落地。\n5.对技术有持续热情与好奇心，乐于探索新技术方向与工程方法，并将探索转化为实际成果。\n6.在既有技术领域有扎实积累，能将复杂系统与平台建设经验应用到 Agent、LLM 及模型训练场景中。\n加分项\n1.有大规模数据管理、跨集群数据流转或数据基础设施相关经验。\n2.参与过 LLM 训练、Post-Training、Benchmark/Eval、Agent 研发或模型研发平台建设。\n3.实际参与过模型训练，具备数据挖掘、数据","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:2f6838b7-f9ef-457c-8e54-cde45de1f883","sourceKey":"deepseek","company":"DeepSeek","title":"财务团队","city":"拱墅区","category":"财务团队","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/2f6838b7-f9ef-457c-8e54-cde45de1f883","duty":"【团队使命】\n我们是航行巨轮上精准的导航仪，精准核算是我们的导航图，专业是永不熄灭的灯塔。我们用数据预见风险，用模型预测机会，将繁琐的流程自动化，把复杂的报表可视化，以创新思维构建风控防线，开辟价值的新大陆。\n招聘方向【全职】：CFO/财务总监/会计方向、出纳方向\nCFO/财务总监/会计方向\n【工作职责】\n1.参与战略规划和财务战略承接，探索适合发展的商业模式，规划未来全面预算管理体系。\n2.统筹资本运作、投融资并购重组项目，最大化利用资源信息促使公司价值可持续增长。\n3.建立全链条的合规风控体系，推动风险治理符合需求，不断优化组织能力。\n4.主持管理财务工作，包括但不限于会计核算、重/难点财税问题处理、数据统计分析等，为公司经营决策提供落地方案。\n5.与内外部建立良好的合作关系，确保部门运行高效、顺畅，促进各项业务有效开展。\n【工作职责】\n1.负责公司日常现金、对公银行收付、员工报销、供","requirements":"【岗位要求】\n1.国内外顶尖院校，985本科及以上学历优先。\n2.精通会计准则、税收政策，持有CPA优先。\n3.具备良好的职业操守，优异的逻辑思维、沟通协调能力和超越意识，严谨、规范，认同开放共进的企业文化、积极创新、乐于挑战。\n出纳方向\n【岗位要求】\n1.财会相关专业，本科及以上学历，1-3年工作经验。\n2.具备良好的沟通、合作、学习能力，细致认真、踏实勤奋，责任心强。","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:40447266-bdbb-4728-8db4-ed1435408026","sourceKey":"deepseek","company":"DeepSeek","title":"Agent Harness 研究员（实习/全职）","city":"拱墅区/海淀区","category":"其它","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/40447266-bdbb-4728-8db4-ed1435408026","duty":"","requirements":"","description":"投递 Agent Harness 团队的职位请移步【新链接】：Agent Harness 团队","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:43f8551a-4235-4d5e-a9a7-44386cd79795","sourceKey":"deepseek","company":"DeepSeek","title":"大模型训练/推理框架工程师","city":"拱墅区/海淀区","category":"AI核心系统研发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/43f8551a-4235-4d5e-a9a7-44386cd79795","duty":"【团队使命】\nAGI 的成功，离不开对极致工程系统的追求。我们致力于为 AGI 构建基础设施，打造高效、稳定、可扩展的工程系统，支持前沿探索的持续迭代、先进模型的大规模训练、以及面向全社会的极致性价比服务。我们的产出陪伴着每一代模型从能力验证一路走向大规模落地，长期、持续为下一代智能应用提供坚实基础设施底座。\n【岗位类别】：实习/全职\n【工作职责】\n1.建设分布式训练推理系统，包括模型并行、长上下文、MoE、低精度训推等。\n2.建设 RL 训练系统，包括异步 RL、Agent RL、OPD 等。\n3.建设多模态训练系统，包括模型结构搭建、性能显存优化、数据读取加速等。\n4.设计和开发大规模推理服务的 KV Cache 磁盘缓存、负载均衡等策略。\n5.与算法团队协作，支持新模型、新算法快速落地。","requirements":"【岗位要求】\n1.基础扎实，学习能力强，愿意深入复杂系统和底层细节。\n2.代码能力强，代码品味好，擅长与 Code Agent 合作。\n3.对大模型训练、推理、RL、多模态系统优化有强烈兴趣。\n4.熟悉 Python / C++ / Rust 之一，了解 PyTorch。\n【加分项】\n1.在大型开源软件中有深度贡献，或有优秀个人开源项目。\n2.在高性能计算相关赛事（SC / ASC / ISC / PAC 等）或算法竞赛（IOI / NOI / ICPC 等）中取得优异成绩。\n3.熟悉 CUDA / Triton / TileLang / Ascend C 等算子开发。\n4.熟悉 RDMA 编程，CPU / IO 优化。\n5.在校成绩排名前 10%。\n6.复现过 LLM、RL、多模态相关论文 / 项目。\n（我们欢迎没有大模型经验，但计算机基础素质扎实、对 AGI 有热情的同学加入。）","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:50733e68-4b26-4037-8b63-2ed781aa44ed","sourceKey":"deepseek","company":"DeepSeek","title":"测试开发工程师","city":"拱墅区","category":"全栈开发/算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/50733e68-4b26-4037-8b63-2ed781aa44ed","duty":"【团队使命】\nAGI 时代，质量的定义正在被重新书写。AI 赋予了产品主动思考的能力与无限可能，也要求我们以全新的方式守护每一次交互的可靠与卓越。我们正站在质量工程变革的最前沿，将智能融入质量保障的每一个环节，构筑人与 AI 交互的信任基石。在这里，你将：\n1.探索 AGI 时代尚未被定义的质量保障新范式，迈向 AI 驱动的智能质量工程，重塑质量工程的形态与边界。\n2.打造支撑多业务、多终端的全栈质量平台，持续提升全线产品的交付品质与可靠性，守护 DeepSeek 在数千万日活下的每一次极致体验，为下一代人机交互与产品的质量保驾护航。\n【岗位类别】：实习/全职\n【工作职责】\n负责 DeepSeek 业务及系统的质量保障工作，协同产研团队高效高质交付产品。深度参与数千万日活产品及系统的迭代，从产品建设、可测性、稳定性等多个方面构建质量保障体系，共同探索 AI 产品的更多可能性。","requirements":"【岗位要求】\n1.对质量保障有系统的理解，有较强的分析设计能力，能熟练定位系统质量风险并设计方案。\n2.具备一定的开发能力，有测试工具、测试平台的开发经验。\n3.对新技术抱有热情，具备扎实的编程能力和代码品味（熟悉 Go、Rust 优先）。\n4.优秀的跨团队沟通能力，具有强烈的责任心和主观能动性。\n5.具备用户洞察能力，有产品、交互设计相关经验者优先。\n6.有优秀的个人技术产品、开源作品，或活跃的开源社区贡献者优先。","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:54f386a9-913b-4626-9bf4-e1709b62fcda","sourceKey":"deepseek","company":"DeepSeek","title":"Agent Harness 产品经理","city":"拱墅区/海淀区","category":"其它","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/54f386a9-913b-4626-9bf4-e1709b62fcda","duty":"","requirements":"","description":"投递 Agent Harness 团队的职位请移步【新链接】：Agent Harness 团队","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:5d75f4cd-f626-4f73-80c1-e53b2073de76","sourceKey":"deepseek","company":"DeepSeek","title":"后训练（数据/算法）研究员","city":"拱墅区/海淀区","category":"深度学习研究员","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/5d75f4cd-f626-4f73-80c1-e53b2073de76","duty":"","requirements":"","description":"【团队使命】\n通过高质量后训练数据与前沿算法，最大化释放Base模型潜能，打造兼具强大智能与深度意图理解力的AI模型。使得模型既能解决最难的问题，也能读懂每一个意图，更能作为自主Agent在复杂真实世界中可靠地行动。\n【岗位类别】：实习/全职\n【工作职责】\n1.持续迭代与优化强化学习算法，在预训练模型与数据既定的条件下，最大限度地释放模型潜力。\n2.跨部门团队紧密协作，构建高质量、高多样性的后训练数据集；设计并落地自动化数据清洗、评测及合成管线，系统性提升模型在写作、问答、Agent 等核心场景的表现。\n3.建立科学、敏捷、多维度的模型能力评测体系，覆盖通用能力与 Agent 场景，精准定位模型短板并驱动针对性优化。\n【岗位要求（满足其一即可）】\n1.对大模型后训练有深入理解，熟悉 RLHF / RLVR / PPO / GRPO 等主流强化学习框架与范式，具备从算法设计到工程落地的完整经","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:647a8853-3707-4cb6-a4cd-7e582da27774","sourceKey":"deepseek","company":"DeepSeek","title":"AGI核心业务管培生","city":"拱墅区/海淀区","category":"AGI核心业务管培生","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/647a8853-3707-4cb6-a4cd-7e582da27774","duty":"","requirements":"","description":"【团队使命】\n在这里，你将深入公司核心业务，在真实场景中历练成长，逐步成为公司AGI事业成功之路上不可或缺的中坚力量，用你的专业能力与实践经验，为这一事业从愿景走向现实提供关键支撑。\n1.针对每位管培生的特点，我们将结合业务需要，安排你进入核心业务中一个方向深耕。\n2.你将获得充分的资源支持与宽阔的成长路径，逐步成长为未来的业务骨干或团队负责人——你的发展节奏，由你自己来掌握。\n【岗位类别】：实习/全职\n【希望你】：\n1.来自国内外顶尖院校，应届毕业生或工作3年以内。\n2.有想法、肯实干、敢创新、愿意挑战自我。\n3.不墨守成规，乐于探索新的可能性。\n4.对AI及大模型行业有浓厚兴趣，持续关注该领域的技术动态与应用场景。","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:7dcd6fde-84f1-4deb-890c-f1f275df0efc","sourceKey":"deepseek","company":"DeepSeek","title":"多模态理解（数据/算法）研究员","city":"拱墅区/海淀区","category":"深度学习研究员","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/7dcd6fde-84f1-4deb-890c-f1f275df0efc","duty":"","requirements":"","description":"【团队使命】\nAGI 绝不会止步于文本，迈向 AGI 的关键一环，在于让模型拥有理解物理世界的能力。我们的使命，是为 AI 注入“看懂并理解世界”的多模态灵魂，让模型在面对复杂的真实世界时，依然能展现出精准的感知与推理能力。在这里，你将会挑战多模态领域的本质难题：处理海量且充满噪声的多模态数据，设计底层的高效原生模型架构，探索大规模训练策略，建立反映真实需求的评测基准。跨越数据、架构、训练与评测的全链路，让多模态成为解决现实挑战的核心生产力。\n【岗位类别】：实习/全职\n【工作方向】\n覆盖多模态理解基座模型全链路，包含：视觉编码器优化 / 多模态预训练 / 多模态后训练 / 评测体系建设（候选人可选其中1个或多个方向）。\n【工作职责】\n1.负责多模态基座模型的迭代。探索视觉编码器和 VLM 的结构、训练策略和评测方式，针对多模态场景持续验证和迭代预训练与后训练（SFT / RL / OPD）","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:7dfbdfc9-d61f-481e-ab19-954c10b8f763","sourceKey":"deepseek","company":"DeepSeek","title":"法务团队","city":"拱墅区","category":"法务团队","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/7dfbdfc9-d61f-481e-ab19-954c10b8f763","duty":"","requirements":"","description":"【团队使命】\n作为AGI公司法务团队，我们的使命早已超越了传统的风险控制。我们视规则为土壤，滋养创新，而不仅是用条款去束缚它；我们用法律的温度守护公司的初心，让每一次商业决策都闪耀人性的善意。我们不仅是底线的捍卫者，更是价值的共创者——确保对用户的每一个承诺坚实可信，让员工的每一份托付得到尊重，使企业在奔赴星辰大海的征途中，始终与责任和良知同行。我们的使命，就是为情怀披上盔甲，为理想保驾护航。\n【岗位类别】：全职\n【核心要求】\n1.国内外知名院校法律本科及以上学历，通过法律职业资格考试。\n2.对人工智能技术、产品和行业有很强的好奇心。\n3.具备优秀的学习能力、判断能力、逻辑思维能力，能用创新方法解决问题。\n4.有很好的法律素养，又兼备敏锐的商业直觉，思考和处理问题有全局观。\n5.乐观坚韧，积极主动，有团队精神。","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:8a4c2868-599d-40db-be4d-ab58eec5d7e1","sourceKey":"deepseek","company":"DeepSeek","title":"预训练数据工程师","city":"拱墅区/海淀区","category":"全栈开发/算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/8a4c2868-599d-40db-be4d-ab58eec5d7e1","duty":"【团队使命】\n预训练数据开采自人类世界全部已有知识所沉积的富矿，是驱动模型强大能力的核心燃料。\n预训练数据团队围绕大模型预训练，构建了从数据采集、清洗处理到底层基础设施的完整数据体系，持续为模型训练输送高质量、规模化、多模态的数据燃料，不断拓展模型的世界知识边界。\n如何寻找蒙尘的富矿，并淘洗炼制成可用的智能燃料，是一门极难的硬功夫。我们以亿万数据筑就模型智能的坚实底座，更要用普惠的方式，把这份属于全人类的财富，重新还给全人类。\n招聘方向【实习/全职】：数据采集 pipeline 方向、语言数据处理方向、多模态数据方向、数据基建方向。\n数据采集 pipeline 方向\n【岗位职责】\n1.全网数据选取策略设计开发\n(1)根据数据清洗反馈信号设计全网数据选取、调度系统，包括链接质量预估、属性聚合、站点抓取配额、数据优先级等，保证数据多样性，最大化数据覆盖，为模型训练提供丰富的世界知识。\n(2)面","requirements":"【岗位要求】\n1.计算机或数学相关专业，本科及以上学历。\n2.熟练使用至少一种编程语言，包括但不限于 Python/C++/Rust。\n【加分项】\n1.数学或信息学竞赛中取得优秀成绩。\n2.有大规模数据采集、爬虫或数据 pipeline 系统研发经验。\n语言数据处理方向\n【岗位要求】\n1.计算机、人工智能相关专业，本科及以上学历。\n2.熟练使用 Python 及任意一种常用数据处理工具链（pandas / spark / duckdb 等）。\n【加分项】\n1.对世界有好奇心，对模型行为有自己独特的理解。\n2.对模型能力边界有敏锐判断，善于发现模型在真实场景中的短板和失效模式。\n3.优秀的跨团队沟通能力，能与标注、产品、工程等多角色高效协作。\n4.有大规模数据清洗 pipeline 落地经验（TB级别 tokens）。\n多模态数据方向\n【岗位要求】\n1.计算机基础扎实，熟悉 Python，了","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:8d40c764-d2b2-49b1-826c-e3f2adb75c01","sourceKey":"deepseek","company":"DeepSeek","title":"Agent Harness 团队","city":"拱墅区/海淀区","category":"全栈开发/算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/8d40c764-d2b2-49b1-826c-e3f2adb75c01","duty":"加入 DeepSeek Harness 团队，探索 Agent Harness 方向的未知前沿。\n【团队使命】\nModel + Harness = Agent\n我们正在以研究、工程、产品相结合的方式，把 DeepSeek 的模型能力转化为前沿的科研突破与领先的 Agent 产品。\n你将加入 Harness 团队，探索 Harness 领域的研究、工程与产品前沿，定义 DeepSeek 对 Harness 的理解。\n招聘方向：深度学习研究员、研发工程师、开发者关系、产品经理、产品设计师、项目经理、产品运营。\n各个招聘方向均可实习或全职。\n深度学习研究员方向\n加入 DeepSeek Harness 团队，探索 Agent Harness 方向的研究前沿。全职、实习均可。\n【主要职责】\n与 Harness 团队的研究员与工程师深度沟通、紧密合作，共同定义和实现 Harness 领域基于模型能力的","requirements":"【任职要求】\n2年以上计算机科学或相关领域的科研经验，水平过硬，眼界广阔，有科研品味。特别优秀候选人可放宽年限。\n硕士学历及以上。特别优秀候选人可放宽。\n计算机科学领域具有含金量的科研成果。\n面对问题能够独立分析并提出自己的 idea，具备从 0 到 1 推动研究的能力。能够快速将想法转化为可运行的原型，具备高效的实验迭代能力。\n熟练使用 AI Agent 工具进行软件开发。在软件开发领域具有极强的学习能力。能够在 AI 辅助下，在没有直接经验的领域（如语言、技术、框架等）进行研究目的的编程工作。\n是 Agent 产品的高强度用户，对 Agent Harness 的开发和研究有极大的热情，对模型行为有品味有判断力。深度使用过代码类及通用类Agent产品，并将相关产品的使用融入到自己的工作和生活中。\n熟悉 LLM 以及 Agent 基本机制及其技术原理，包括 LLM API、KV Cache","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:97ecb322-fa87-47f3-8c1e-e66edfbd34fc","sourceKey":"deepseek","company":"DeepSeek","title":"采购团队","city":"拱墅区/察哈尔右翼前旗","category":"采购团队","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/97ecb322-fa87-47f3-8c1e-e66edfbd34fc","duty":"【团队使命】\n集结顶尖采购人才，为 AGI 时代搭建核心基建，用每一次寻源拓宽算力边界，用每一次计划校准供需节奏，用每一次采购定义算力上限。\n招聘方向【全职】：硬件采购方向、云服务采购方向、IDC采购方向、数据中心资产管理方向、采购管培方向\n硬件采购方向\n【工作职责】\n负责算力服务器（含AI服务器、通用服务器）及核心配件（GPU、CPU、内存、硬盘、网卡、光模块等）的采购全流程工作。\n【工作职责】\n负责公司云业务（包括但不限于国内外主流公有云计算服务）的需求分析、市场调研、商务谈判、采购全流程工作;统筹公司软件服务、SaaS服务等采购工作，制定采购策略与供应商管理策略。\n【工作职责】\n负责数据中心资源评估、商务谈判及合同条款设计，维护数据中心、运营商、设备厂商等合作伙伴关系；跟踪行业趋势及市场动态，为业务决策提供支持。\n【工作职责】\n1.负责数据中心及库房资产的管理维护，对机房设备出入库、","requirements":"【岗位要求】\n1.本科及以上学历，计算机/电子类等理工科专业背景。\n2.正直可靠，逻辑清晰，具备优秀的自驱力，良好的商务谈判及解决问题的能力。\n云服务采购方向\n【岗位要求】\n1.本科及以上学历，理工科专业背景尤佳。\n2.熟悉公有云计算产品，SaaS类服务，理解公司核心业务指标需求。\n3.正直可靠，逻辑清晰，具备优秀的自驱力，良好的商务谈判及解决问题的能力。\nIDC采购方向\n【岗位要求】\n1.本科及以上学历，理工类专业背景或互联网/数据中心/云计算/电力行业经验加分。\n2.具备优秀的沟通协调、商务谈判和问题解决能力，能够在复杂环境下推动事情向前发展。\n3.保持好奇心和学习能力，对AI、算力基础设施及大型工程项目充满兴趣，愿意与团队共同成长。\n数据中心资产管理方向\n【岗位要求】\n1.全日制本科及以上学历，物流管理或计算机类相关专业。\n2.一年以上库房及资产管理经验，熟悉服务器相关配件，熟练使用","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:a4ad8628-286e-4395-ac3e-b8117ac695c6","sourceKey":"deepseek","company":"DeepSeek","title":"Code Agent 数据工程师","city":"海淀区","category":"模型数据策略","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/a4ad8628-286e-4395-ac3e-b8117ac695c6","duty":"","requirements":"","description":"【团队使命】\nCode 定义了 Agent 的能力边界，是 Agent 和物理世界交互的纽带。理解需求、设计方案、实现、验证，在完整的问题解决过程中，每一步都要求精确可运行。Code 能力是模型在这一过程中从“能分析”到“能执行”的关键要素，而模型在真实复杂场景中解决工程问题的能力则是通用智能最务实的度量标准。我们要做的，是通过高质量的训练环境与精准评估体系，系统性地推高这一能力的上限，直到模型真正能独立驾驭复杂软件工程的开发，那将会是我们可以预见的 AGI 临界点之一。\n这是一个 AI 时代的新型工程师岗位。你不需要写业务代码、交付产品，而是用独到的经验和品味，去发现问题、定义评测标准、改进训练数据，教大模型更好地写代码。\n招聘方向【实习/全职】： 前端专项、移动端专项、后端专项、Web 3D 与渲染专项、游戏开发专项、网络安全专项\n【工作职责】\n1.构建强化学习环境：将真实的代码工程、","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:a63f2346-b672-4c48-af43-0a64bfe97a41","sourceKey":"deepseek","company":"DeepSeek","title":"研发基础设施工程师","city":"拱墅区/海淀区/海淀区","category":"AI核心系统研发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/a63f2346-b672-4c48-af43-0a64bfe97a41","duty":"","requirements":"","description":"【关于这个岗位】\nLLM 的成功是 AI 基础设施的成功。在训练 / 推理框架、算子和编译器、文件系统这些「单点极致」之外，还需要有人把整个系统栈串起来。我们不设限于具体的技术栈或语言 —— 我们在寻找的是那种对计算机系统（从机房里的铁疙瘩到内核再到上层框架）有广泛好奇心、动手能力极强的系统工程师（Hacker / Geek）：各种领域都懂一点、在不少领域懂很多，遇到问题不挑活儿，撸起袖子就能解决。\n【工作职责】\n1.深入研发工程链路的各个层面 —— 大型集群管理、运行时、文件系统、构建与打包分发、环境与镜像更新维护、即时编译（JIT）和 CI/CD 等 —— 发现并解决影响团队迭代效率和稳定性的各类问题。\n2.积极搭建和维护各类自动化工具和工程基础设施，让研究和工程团队跑得更快、更稳。\n3.作为团队的粘合层，与训练 / 推理框架、算子和编译器等团队协作，定位跨层疑难杂症，推动系统性改进落","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:a7355097-fd57-4219-99a5-8963745d362f","sourceKey":"deepseek","company":"DeepSeek","title":"高性能分布式存储工程师","city":"拱墅区","category":"AI核心系统研发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/a7355097-fd57-4219-99a5-8963745d362f","duty":"【团队使命】\n在大模型时代，数据与存储是智能的基石。让任何AI应用都能以零妥协的性能和无限扩展能力持续获取数据——存储不仅是承载信息的底座，更是决定AI成本与极致体验的核心引擎。\n【岗位类别】：实习/全职\n【岗位职责】\n1.设计与开发支撑大模型推理的高性能、高可用 KVCache 存储系统，在毫秒级延迟和上亿级 IOPS 下保障系统稳定，用底层的技术突破直接颠覆公司核心产品的性价比与用户体验。\n2.设计与开发下一代分布式文件系统和对象存储系统，为超大规模训练提供极致带宽与稳定数据链路，为分布式数据处理提供强一致的共享存储层。","requirements":"【岗位要求】\n1.扎实的 Rust/C++ 编程能力，精通多线程、异步编程及系统性能分析。\n2.熟悉分布式系统原理，深入理解并实践过分布式事务、Paxos/Raft 等共识机制。\n3.能灵活运用经典文献及顶尖开源系统中的设计范式和经验（如 RocksDB、FoundationDB、ClickHouse 等），而非简单套用与组合。致力于从第一性原理出发，用简单优雅的方案解决问题。\n【加分项】\n1.具备开发和应用零拷贝数据链路的经验，熟悉基于 RDMA 实现高吞吐、低延迟的通信方法，致力于榨干现代网络硬件的性能极限。\n2.设计并开发过 SSD/HDD 上的高性能本地存储引擎，熟练掌握基于 io_uring/SPDK 的实现，能在存储硬件极限上做文章。\n3.实现过 Linux 内核文件系统，或深入解决过 FUSE 在性能与可维护性上的痛点，对内核 I/O 栈有第一手经验。\n4.在 OSDI/FA","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:a7a0d39e-a15b-4dac-909c-0ce26fbb950e","sourceKey":"deepseek","company":"DeepSeek","title":"行政团队","city":"拱墅区/海淀区","category":"行政团队","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/a7a0d39e-a15b-4dac-909c-0ce26fbb950e","duty":"","requirements":"","description":"【团队使命】\n我们将人、空间、资源与文化连接在一起，是组织高速前进时不可或缺的神经系统。我们致力于用专业与敏锐守护团队的效率、体验与温度，让每一位投身 AGI 建设的人都能感到被支持、被理解、被成全。我们在细微处托举宏大使命，让未来更快、更稳地到来。\n【岗位类别】：实习/全职\n我们在找这样的人\n1.不满足于“把事情做完”，而是执着于“把体验做好”。\n2.能在细节里发现机会，在琐碎中创造秩序。\n3.相信 AI 可以赋能行政工作，也相信人的温度无可替代。\n如果你也是这样——\n欢迎加入我们，一起为那些改变世界的人，创造一个他们不想离开的地方。","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:aed2a32c-189f-4338-b901-9b45d2b7edfd","sourceKey":"deepseek","company":"DeepSeek","title":"高性能算子/通信/编译器工程师","city":"拱墅区/海淀区","category":"AI核心系统研发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/aed2a32c-189f-4338-b901-9b45d2b7edfd","duty":"","requirements":"","description":"【团队使命】\n我们构建 AGI 与物理芯片之间的最后一层软件，为训练推理框架和研究员提供高性能的计算算子、集合通信和领域编译器，同时也是模型设计和硬件 co-design 的桥梁。\n团队的唯一标准：硬件的物理极限。我们不和任何 baseline 或者其他实现比较性能差异，只关心当前设计和实现距离理论上限还有多远，对每一个 cycle 和每一瓦功耗有着近乎偏执的追求。\n我们为上层框架和研究员提供稳定的接口，使底层的高性能实现以使用友好、可靠且可维护的方式融入整个系统。\n加入我们，你将同时深入 NVIDIA GPU 和 Ascend NPU 等国产硬件，从指令集、内存模型、编译栈到大规模互联，系统性地掌握多种硬件体系。我们不在意你是否有相关背景 —— 我们会尽可能提供必要的指导，但需要的是你对细节的严谨和对性能优化的热情。\n【岗位类别】：实习/全职\n【工作职责】\n1.针对 GPU/NPU 等架","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:b48bdca9-742f-44f1-bde8-5c4e9b953f31","sourceKey":"deepseek","company":"DeepSeek","title":"AI平台运维工程师","city":"拱墅区","category":"运维","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/b48bdca9-742f-44f1-bde8-5c4e9b953f31","duty":"【团队使命】\n在AGI的纪元，竞争的本质已升维为超大规模算力系统性能与可靠性的终极角力——这远非机械性的运维，而是以架构师之姿，亲手浇筑智能时代的“重力场”。我们不满足于守护算力的灯火，更致力于让万卡集群的澎湃算力化作如水电般无形却无处不在的基座：在纳秒级的延迟中雕琢极致，在洪流般的训练中锚定永恒稳定，将复杂的底层逻辑隐于幕后，让业务方只感知到“丝滑”与“确定”的纯粹体验。这不仅是构建平台，更是托举AGI进化的桥梁——我们拒绝被动的应急，选择主动定义未来，让每一次模型迭代都踏在坚实可靠的算力底座之上，直至智能的彼岸因我们的存在而触手可及。\n招聘方向【实习/全职】: 集群运维方向、运维开发方向\n集群运维方向\n【我们在找什么样的人】\n如果你对实现AGI这件事有强烈的兴趣和好奇心——不是因为风口热，而是你真的觉得\"造出通用人工智能\"是这个时代最值得投入的事情——那我们想认识你。\n我们不太在意你过","requirements":"【任职要求】\n1.本科及以上学历。\n2.较好的 Python/Golang 等开发能力，扎实的工程能力。\n3.对运维体系有较全面的认知，深入理解运维流程。\n4.熟悉CMDB、工单系统等运维平台。\n5.较好的沟通能力和理解能力。\n【加分项】\n1.3年以上一线运维经历，深知运维痛点。\n2.熟悉SRE体系。\n3.成熟运维平台开发经历。","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:b8e62d9e-5cfb-4f24-bb6b-549bf45e1ee0","sourceKey":"deepseek","company":"DeepSeek","title":"情感智能数据产品经理","city":"拱墅区/海淀区","category":"模型数据策略","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/b8e62d9e-5cfb-4f24-bb6b-549bf45e1ee0","duty":"【团队使命】\n情感仍然是 AI 时代人类与自身相处时必须面对的课题。它并不处在智能的对立面，而是在每一次与 AI 的联结中引导我们照见自己。从人本身最天然的情感认知出发，观察感受、思维和情绪如何在人与 AI 的交互之间流动，关注模型对于故事、关系与人的理解和表达，用细腻有温度的洞察力，思考并探索人机互动的更新形态、情感内核与多元底色。\n【岗位类别】：实习/全职\n【工作职责】\n1.负责 DeepSeek 模型在角色扮演与情感陪伴场景下的能力优化，提升互动体验的真实感与沉浸度。\n2.深入挖掘角色扮演与情感陪伴场景中的 Badcase，进行归因分析并推动问题解决。","requirements":"【岗位要求】\n1.文字审美敏锐，感知力强，思维活跃且富有同理心，具备出色的洞察、分析与解决问题能力。\n2.对 AI 与人的互动关系有细致观察和独立思考，对 AI 角色扮演及情感陪伴有自己的经验理解并充满探索热情。\n3.深度使用过前沿主流大模型，熟悉其交互特点与能力边界；能通过 Vibe Coding 快速验证想法。\n4.沟通积极协作顺畅，善于快速主动学习，内驱力强，有高度责任心和 Owner 意识。\n5.熟悉模型训练基本原理、有模型优化数据生产与系统性评测经验者优先。","description":"","jdComplete":true,"sourceStatus":"open"},{"id":"deepseek:bae809fb-1978-4401-b209-34067b26569d","sourceKey":"deepseek","company":"DeepSeek","title":"Agent  弹性计算研发工程师","city":"拱墅区/海淀区","category":"全栈开发/算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://app.mokahr.com/social-recruitment/high-flyer/140576#/job/bae809fb-1978-4401-b209-34067b26569d","duty":"【团队使命】\nDSec 是我们为 Agent 量身定制的弹性计算平台，托管着成千上万个沙箱环境，正有序推进着下一代模型的迭代。为了增加可靠性和效率，DSec 需要修改整个系统栈：从操作系统到虚拟机，再到各级网络和存储，一直上到应用层调度和管控面服务。\n在这里，理解需求是一切的起点——很多事情前人没有做过，没有现成的答案可抄。你将与顶级的开发者和研究员们一起讨论、了解、推进、满足用户最根本的需求，并用尽可能优雅的方式把需求融入到不断迭代的 Agent 弹性计算平台上，使其能与前沿模型共同演进。\n同时，也需要解决小到自旋锁，大到跨区域数据一致性的各类系统问题，并应对无监管全自动运行 Agent 带来的安全挑战——过往对负载、隔离、用量、安全的假设不再成立，需要另辟蹊径。\n【岗位类别】：实习/全职\nDSec 下设平台开发和底层系统两个方向，投递时不限方向，我们会根据你的背景与意愿确定具体方向，也","requirements":"岗位要求\n基本背景：\n1.计算机或其他相关专业，本科及以上学历。\n2.扎实的编程与工程能力（Rust / C++ / Python 等均可），以及对简洁明了、可维护代码的基本美学素养。\n3.能有效捕捉用户的需求，把模糊的想法抽象成清晰的方案，并将未来需求有序地融合到大型系统的开发进度中。\n4.有良好的沟通能力和团队协作能力。\n满足下列任意一条即可：\n1.开发或长期维护过面向用户的 API、SDK 或服务端系统，对接口设计、数据建模与版本演进有实际理解。\n2.深入了解大规模分布式系统的组织方式，清楚架构瓶颈产生的原因和与之相关的 trade-off。\n3.熟练运用压测和可观测性工具，具备在生产环境中定位复杂问题、直击根因的能力。\n4.理解可靠系统的设计，对系统稳定性有强烈的责任心，并且有意识地确保前人的事故不会在当下重演。\n5.有过大型系统的自动化运维、应急响应经验，或建设过 Log / m","description":"","jdComplete":true,"sourceStatus":"open"}];
